        emon.Testport.assertEq(Retarget.rtPermille(3000000, (2550 * 3300) + 1), 356, "a share of 8 415 001 pixels");
        emon.Testport.assertEq(Retarget.rtPermille(1, 2), 500, "and a small one is as it was");
